from typing import List
from app.ml.schema import ArchitectureGraph
from app.ml.validator import ArchitectureValidator


class PyTorchCodeGenerator:
    """
    Generates clean, idiomatic, standalone PyTorch code from an ArchitectureGraph.
    """

    @classmethod
    def generate(cls, graph: ArchitectureGraph) -> str:
        val = ArchitectureValidator.validate_graph(graph)
        shape_map = {s.node_id: s for s in val.layer_shapes}
        node_map = {n.id: n for n in graph.nodes}

        lines: List[str] = [
            "# Auto-generated by Neural Network Architecture Studio (NNAS)",
            f"# Architecture: {graph.name} (v{graph.version})",
            f"# Total Parameters: {val.total_parameters:,} (Trainable: {val.trainable_parameters:,})",
            "",
            "import torch",
            "import torch.nn as nn",
            "",
            "",
            f"class {cls._clean_class_name(graph.name)}(nn.Module):",
            "    def __init__(self):",
            "        super().__init__()",
        ]

        # Init layers
        init_lines: List[str] = []
        forward_lines: List[str] = ["        # Forward pass through layers"]

        curr_var = "x"

        for node_id in val.execution_order:
            node = node_map[node_id]
            if node.type == "Input":
                continue

            shape_info = shape_map.get(node_id)
            in_shape = shape_info.input_shape if shape_info else [64]
            var_name = f"layer_{node.id.replace('-', '_')}"
            layer_def = cls._format_layer_def(node.type, node.parameters or {}, in_shape)
            init_lines.append(f"        self.{var_name} = {layer_def}")
            forward_lines.append(f"        {curr_var} = self.{var_name}({curr_var})")

        if not init_lines:
            init_lines.append("        pass")

        lines.extend(init_lines)
        lines.append("")
        lines.append("    def forward(self, x: torch.Tensor) -> torch.Tensor:")
        lines.extend(forward_lines)
        lines.append(f"        return {curr_var}")
        lines.append("")
        lines.append("")
        lines.append("if __name__ == '__main__':")
        lines.append(f"    model = {cls._clean_class_name(graph.name)}()")
        lines.append("    print(model)")
        sample_shape = [1] + list(graph.input_shape)
        lines.append(f"    sample_input = torch.randn({sample_shape})")
        lines.append("    output = model(sample_input)")
        lines.append("    print(f'Input shape:  {sample_input.shape}')")
        lines.append("    print(f'Output shape: {output.shape}')")

        return "\n".join(lines)

    @staticmethod
    def _clean_class_name(name: str) -> str:
        clean = "".join(ch for ch in name.title() if ch.isalnum())
        if not clean or clean[0].isdigit():
            clean = "NNASModel"
        return clean

    @staticmethod
    def _format_layer_def(layer_type: str, params: dict, in_shape: list) -> str:
        if layer_type in ("Linear", "Dense"):
            out_features = params.get("out_features", 64)
            bias = params.get("bias", True)
            in_features = in_shape[-1]
            return f"nn.Linear(in_features={in_features}, out_features={out_features}, bias={bias})"

        elif layer_type == "Conv2d":
            in_c = in_shape[0]
            out_c = params.get("out_channels", 32)
            k = params.get("kernel_size", 3)
            s = params.get("stride", 1)
            p = params.get("padding", 1)
            bias = params.get("bias", True)
            return f"nn.Conv2d(in_channels={in_c}, out_channels={out_c}, kernel_size={k}, stride={s}, padding={p}, bias={bias})"

        elif layer_type == "MaxPool2d":
            k = params.get("kernel_size", 2)
            s = params.get("stride", 2)
            p = params.get("padding", 0)
            return f"nn.MaxPool2d(kernel_size={k}, stride={s}, padding={p})"

        elif layer_type == "AvgPool2d":
            k = params.get("kernel_size", 2)
            s = params.get("stride", 2)
            p = params.get("padding", 0)
            return f"nn.AvgPool2d(kernel_size={k}, stride={s}, padding={p})"

        elif layer_type == "Flatten":
            start_dim = params.get("start_dim", 1)
            return f"nn.Flatten(start_dim={start_dim})"

        elif layer_type == "ReLU":
            return "nn.ReLU()"

        elif layer_type == "Sigmoid":
            return "nn.Sigmoid()"

        elif layer_type == "Tanh":
            return "nn.Tanh()"

        elif layer_type == "Softmax":
            dim = params.get("dim", -1)
            return f"nn.Softmax(dim={dim})"

        elif layer_type == "Dropout":
            p = params.get("p", 0.2)
            return f"nn.Dropout(p={p})"

        elif layer_type == "BatchNorm1d":
            eps = params.get("eps", 1e-5)
            momentum = params.get("momentum", 0.1)
            return f"nn.BatchNorm1d(num_features={in_shape[-1]}, eps={eps}, momentum={momentum})"

        elif layer_type == "BatchNorm2d":
            eps = params.get("eps", 1e-5)
            momentum = params.get("momentum", 0.1)
            return f"nn.BatchNorm2d(num_features={in_shape[0]}, eps={eps}, momentum={momentum})"

        elif layer_type == "TransformerEncoder":
            d_model = params.get("d_model", 64)
            nhead = params.get("nhead", 4)
            dim_ff = params.get("dim_feedforward", 128)
            num_l = params.get("num_layers", 2)
            drop = params.get("dropout", 0.1)
            return f"nn.TransformerEncoder(nn.TransformerEncoderLayer(d_model={d_model}, nhead={nhead}, dim_feedforward={dim_ff}, dropout={drop}, batch_first=True), num_layers={num_l})"

        return f"# Unsupported layer: {layer_type}"
